'use client';

import React, { useState } from 'react';
import styles from './orders.module.css';

// Mock Orders for Zero-DB Mode
const INITIAL_MOCK_ORDERS = [
    {
        _id: '1',
        orderId: 'JK8274',
        createdAt: new Date().toISOString(),
        customerName: 'Anbu Selvan',
        mobileNumber: '9845012345',
        address: '12, South Street, Thoothukudi',
        product: { name: 'Sankara Karuvadu', finalPrice: 405 },
        quantity: 2,
        status: 'DELIVERED'
    },
    {
        _id: '2',
        orderId: 'JK9102',
        createdAt: new Date().toISOString(),
        customerName: 'Muthu Krishnan',
        mobileNumber: '9765109283',
        address: 'Beach Road, Tiruchendur',
        product: { name: 'Nethili Karuvadu', finalPrice: 272 },
        quantity: 5,
        status: 'PENDING'
    },
    {
        _id: '3',
        orderId: 'JK3341',
        createdAt: new Date().toISOString(),
        customerName: 'Ranjith Kumar',
        mobileNumber: '9988776655',
        address: 'Anna Nagar, Madurai',
        product: { name: 'Vanjiram Karuvadu', finalPrice: 1140 },
        quantity: 1,
        status: 'SHIPPED'
    }
];

export default function AdminOrders() {
    const [orders, setOrders] = useState(INITIAL_MOCK_ORDERS);

    const handleStatusChange = (id: string, newStatus: string) => {
        setOrders(orders.map(o => o._id === id ? { ...o, status: newStatus } : o));
    };

    return (
        <div className={styles.container}>
            <div className={styles.header}>
                <h1>Manage Orders</h1>
            </div>

            <div className={styles.orderTableWrapper}>
                <table className={styles.table}>
                    <thead>
                        <tr>
                            <th>Order ID</th>
                            <th>Date</th>
                            <th>Customer</th>
                            <th>Product</th>
                            <th>Qty</th>
                            <th>Total</th>
                            <th>Status</th>
                        </tr>
                    </thead>
                    <tbody>
                        {orders.map((o) => (
                            <tr key={o._id}>
                                <td><strong>{o.orderId}</strong></td>
                                <td>{new Date(o.createdAt).toLocaleDateString()}</td>
                                <td>
                                    <div className={styles.customerDetail}>
                                        <span className={styles.custName}>{o.customerName}</span>
                                        <span className={styles.custMobile}>{o.mobileNumber}</span>
                                        <span className={styles.custAddr}>{o.address}</span>
                                    </div>
                                </td>
                                <td>{o.product?.name || 'Unknown'}</td>
                                <td>{o.quantity} Kg</td>
                                <td>₹{(o.product?.finalPrice || 0) * o.quantity}</td>
                                <td>
                                    <select
                                        value={o.status}
                                        onChange={(e) => handleStatusChange(o._id, e.target.value)}
                                        className={`${styles.statusSelect} ${styles[o.status.toLowerCase()]}`}
                                    >
                                        <option value="PENDING">Pending</option>
                                        <option value="SHIPPED">Shipped</option>
                                        <option value="DELIVERED">Delivered</option>
                                        <option value="CANCELLED">Cancelled</option>
                                    </select>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}
